const cfg = {
  nanomdmUrl: 'http://mdm-nanomdm.mdm.svc.cluster.local:9000',
  depserverUrl: 'http://mdm-depserver.mdm.svc.cluster.local:9001',
  scepUrl: 'http://mdm-scep.mdm.svc.cluster.local:8080',
  publicHost: 'mdm-prod.pke-lab.de',
  depName: 'capulus',
  ntfyUrl: 'http://ntfy.ntfy.svc.cluster.local',
  ntfyTopic: 'Home-Lab-MDM',
  vmUrl: 'http://vmsingle-monitoring-victoria-metrics-k8s-stack.monitoring.svc.cluster.local:8428',
  n8nUrl: 'https://n8n.prod.homeserver'
};
cfg.ntfyTopic = 'Home-Lab-iPad';
return [{ json: cfg }];

const item = $input.first();
const fail = (text) => [{ json: { ok: false, title: 'Nichts gesendet', message: text } }];
const names = Object.keys(item.binary || {});
if (names.length === 0) return fail('Es wurde keine Datei hochgeladen.');
const file = item.binary[names[0]];
const buffer = await this.helpers.getBinaryDataBuffer(0, names[0]);
if (buffer.length === 0) return fail('Die Datei ist leer.');
if (buffer.length > 1024 * 1024) return fail('Die Datei ist groesser als 1 MB. Bitte kuerzen oder aufteilen.');
if (buffer.includes(0)) return fail('Das ist keine Textdatei (enthaelt Binaerdaten).');
const input = $('Formular Textdatei').first().json;
const title = String(input['Titel'] || '').trim();
if (title.length > 80) return fail('Der Titel darf hoechstens 80 Zeichen lang sein.');
const original = String(file.fileName || 'datei.txt');
const dot = original.lastIndexOf('.');
const ext = dot > 0 ? original.slice(dot).replace(/[^A-Za-z0-9.]/g, '').slice(0, 8) : '.txt';
const stem = (dot > 0 ? original.slice(0, dot) : original).replace(/ß/g, 'ss').normalize('NFKD').replace(/[̀-ͯ]/g, '').replace(/[^A-Za-z0-9_-]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 60) || 'datei';
const mime = (value) => '=?UTF-8?B?' + Buffer.from(value, 'utf8').toString('base64') + '?=';
const filename = stem + (ext.length > 1 ? ext : '.txt');
const kb = Math.max(1, Math.round(buffer.length / 1024));
const level = String(input['Dringlichkeit'] || '');
const priority = level.indexOf('Dringend') === 0 ? 5 : level === 'Hoch' ? 4 : 3;
return [{
  json: {
    ok: true,
    filename,
    bytes: buffer.length,
    priority,
    titleHeader: mime(title || 'Textdatei'),
    messageHeader: mime(original + ' (' + kb + ' KB) zum Oeffnen antippen')
  },
  binary: { data: file }
}];

const res = $input.first().json;
const sent = $('Datei pruefen').first().json;
if (res.statusCode === 200) {
  return [{ json: { title: 'Datei gesendet', message: sent.filename + ' (' + Math.max(1, Math.round(sent.bytes / 1024)) + ' KB) wurde an das Topic Home-Lab-iPad gesendet. iPads mit der ntfy-App und dem Benutzer ipad sehen sie sofort und koennen sie oeffnen. Der Anhang bleibt auf dem ntfy-Server und laeuft dort nach der eingestellten Aufbewahrungszeit (Standard 3 Stunden) ab.' } }];
}
return [{ json: { title: 'Senden fehlgeschlagen', message: 'ntfy antwortete mit HTTP ' + (res.statusCode || res.error || 'keine Antwort') + '. Pruefen, ob das Credential ntfy-publisher auf Home-Lab-iPad schreiben darf und die Datei kleiner als 5 MB ist.' } }];
